package com.yeshoda.medical.service;
import com.yeshoda.medical.dto.AppointmentRequest; import com.yeshoda.medical.model.*; import com.yeshoda.medical.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AppointmentService {private final AppointmentRepository appointments;private final UserRepository users;private final DoctorRepository doctors; public AppointmentService(AppointmentRepository a,UserRepository u,DoctorRepository d){appointments=a;users=u;doctors=d;}
 public Appointment book(AppointmentRequest r){if(appointments.existsByDoctorIdAndAppointmentDateAndAppointmentTimeAndStatus(r.doctorId(),r.date(),r.time(),"BOOKED"))throw new RuntimeException("This time slot is already booked");Appointment a=new Appointment();a.setPatient(users.findById(r.patientId()).orElseThrow());a.setDoctor(doctors.findById(r.doctorId()).orElseThrow());a.setAppointmentDate(r.date());a.setAppointmentTime(r.time());a.setReason(r.reason());return appointments.save(a);} public List<Appointment> byPatient(Long id){return appointments.findByPatientIdOrderByAppointmentDateDescAppointmentTimeDesc(id);} public void cancel(Long id){Appointment a=appointments.findById(id).orElseThrow();a.setStatus("CANCELLED");appointments.save(a);}}
